<script>
'use strict';
/* ------------------------------------------------------------------ */
/* Source data (as provided with the sketch)                            */
/* ------------------------------------------------------------------ */
const DATA = {
  title: '9V battery, 1k series feed with capacitor and 2.2k + LED branch',
  referenceNet: { fixed: 'gnd', drawn: 'gnd' },
  mistakes: [],
  fixed: { components: [
    { id:'B1', type:'battery',  nodes:['vcc','gnd'], value:9,      label:'9V'  },
    { id:'R1', type:'resistor', nodes:['vcc','n1'],  value:1000,   label:'1kΩ' },
    { id:'C1', type:'capacitor',nodes:['n1','gnd'],  value:0.000022,label:'22µF'},
    { id:'R2', type:'resistor', nodes:['n1','n2'],   value:2200,   label:'2.2kΩ'},
    { id:'D1', type:'led',      nodes:['n2','gnd'],  value:null,   label:'LED' }
  ]},
  asDrawn: { components: [
    { id:'B1', type:'battery',  nodes:['vcc','gnd'], value:9,      label:'9V'  },
    { id:'R1', type:'resistor', nodes:['vcc','n1'],  value:1000,   label:'1kΩ' },
    { id:'C1', type:'capacitor',nodes:['n1','gnd'],  value:0.000022,label:'22µF'},
    { id:'R2', type:'resistor', nodes:['n1','n2'],   value:2200,   label:'2.2kΩ'},
    { id:'D1', type:'led',      nodes:['n2','gnd'],  value:null,   label:'LED' }
  ]}
};
const LED_VF = 2.0;            // generic LED, colour not specified in sketch
const LED_RATED = 0.020, LED_MAX = 0.030;
const BATT_R = 0.2;            // battery internal resistance, ohms
const DEFAULTS = { B1: 9, R1: 1000, R2: 2200, C1: 22e-6 };

/* ------------------------------------------------------------------ */
/* State                                                                */
/* ------------------------------------------------------------------ */
const VALUES = { ...DEFAULTS };
const POSITIONS = {};          // potentiometer wiper positions (none in this netlist)
const SWITCHES = {};           // switch / button states (none in this netlist)
let mode = 'fixed';            // starts in Fixed, per spec
let selectedNet = null;
let S = null;                  // last solve result

const $  = (s, r) => (r||document).querySelector(s);
const $$ = (s, r) => Array.from((r||document).querySelectorAll(s));
const clamp = (v,a,b) => Math.min(b, Math.max(a, v));

/* ------------------------------------------------------------------ */
/* Nodal analysis (Gaussian elimination, LED piecewise-linear model)    */
/* ------------------------------------------------------------------ */
function gauss3(A, b){
  const M = A.map((row,i) => [...row, b[i]]);
  for (let c = 0; c < 3; c++){
    let p = c;
    for (let r = c + 1; r < 3; r++) if (Math.abs(M[r][c]) > Math.abs(M[p][c])) p = r;
    if (Math.abs(M[p][c]) < 1e-12) M[p][c] = 1e-12;
    const tmp = M[c]; M[c] = M[p]; M[p] = tmp;
    for (let r = 0; r < 3; r++){
      if (r === c) continue;
      const f = M[r][c] / M[c][c];
      for (let k = c; k <= 3; k++) M[r][k] -= f * M[c][k];
    }
  }
  return [M[0][3]/M[0][0], M[1][3]/M[1][1], M[2][3]/M[2][2]];
}

function solve(){
  const E = VALUES.B1, R1 = VALUES.R1, R2 = VALUES.R2, vf = LED_VF;
  let ledOn = false, burnt = false;
  let vcc = 0, n1 = 0, n2 = 0, iLed = 0;

  for (let iter = 0; iter < 40; iter++){
    const A = [[0,0,0],[0,0,0],[0,0,0]], b = [0,0,0];
    const gB = 1 / BATT_R;
    // Battery: ideal source E behind BATT_R between vcc(0) and gnd(ref)
    A[0][0] += gB; b[0] += gB * E;
    // R1: vcc(0) - n1(1)
    const g1 = 1 / R1;
    A[0][0] += g1; A[1][1] += g1; A[0][1] -= g1; A[1][0] -= g1;
    // R2: n1(1) - n2(2)
    const g2 = 1 / R2;
    A[1][1] += g2; A[2][2] += g2; A[1][2] -= g2; A[2][1] -= g2;
    // LED: n2(2) - gnd(ref); on model I = (V - vf)/10
    if (ledOn && !burnt){ A[2][2] += 0.1; b[2] += 0.1 * vf; }

    const x = gauss3(A, b);
    vcc = x[0]; n1 = x[1]; n2 = x[2];

    const vak = n2 - 0;
    let iOn = vak > vf ? (vak - vf) / 10 : 0;

    if (!burnt){
      if (ledOn && iOn > LED_MAX + 1e-9){ burnt = true; ledOn = false; continue; }
      const want = vak > vf;
      if (want !== ledOn){ ledOn = want; continue; }
    }
    iLed = (!burnt && ledOn) ? iOn : 0;
    break;
  }

  const iBatt = (E - vcc) / BATT_R;
  const iR1   = (vcc - n1) / R1;
  const iR2   = (n1 - n2) / R2;
  const brightness = clamp(iLed / LED_RATED, 0, 1);

  S = {
    nodes: { vcc, n1, n2, gnd: 0 },
    iBatt, iR1, iR2, iC: 0, iLed,
    vR1: vcc - n1, vR2: n1 - n2, vC: n1, vLed: n2,
    brightness, burnt, ledOn: iLed > 1e-6
  };
}

/* ------------------------------------------------------------------ */
/* Formatting helpers                                                   */
/* ------------------------------------------------------------------ */
const fmtV = v => v.toFixed(2) + ' V';
const fmtI = i => i >= 1e-3 ? (i*1e3).toFixed(2) + ' mA' : (i*1e6).toFixed(1) + ' µA';
const fmtR = v => v >= 1000
  ? String(parseFloat((v/1000).toFixed(2))) + ' kΩ'
  : String(parseFloat(v.toFixed(v < 100 ? 1 : 0))) + ' Ω';
const NET_INFO = [
  { id:'vcc', desc:'battery + to R1' },
  { id:'n1',  desc:'R1 to C1 and R2' },
  { id:'n2',  desc:'R2 to LED anode' },
  { id:'gnd', desc:'bottom rail · 0 V' }
];

/* ------------------------------------------------------------------ */
/* Schematic construction helpers                                        */
/* ------------------------------------------------------------------ */
function zigzag(x1, y1, x2, y2, amp){
  const dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy);
  const ux = dx / len, uy = dy / len, nx = -uy, ny = ux;
  const lead = Math.min(8, len * 0.16);
  const body = len - 2 * lead, N = 6, step = body / (N + 1);
  let d = 'M' + x1 + ',' + y1 + ' L' + (x1 + ux*lead) + ',' + (y1 + uy*lead);
  for (let i = 1; i <= N; i++){
    const s = lead + step * i, off = (i % 2 ? amp : -amp);
    d += ' L' + (x1 + ux*s + nx*off).toFixed(2) + ',' + (y1 + uy*s + ny*off).toFixed(2);
  }
  d += ' L' + x2 + ',' + y2;
  return d;
}

/* Dot flow paths (defined in the direction of conventional current) */
const FLOW = [
  { pts:[[120,126],[120,60],[232,60],[318,60],[420,60],[570,60],[570,94]], cur:() => S.iR1 },
  { pts:[[420,60],[420,150],[420,170],[420,270]],                          cur:() => S.iC  },
  { pts:[[570,96],[570,170],[570,206]],                                    cur:() => S.iR2 },
  { pts:[[570,234],[570,270],[120,270],[120,204]],                         cur:() => S.iBatt }
];
FLOW.forEach(p => {
  p.cum = [0];
  for (let i = 1; i < p.pts.length; i++){
    const a = p.pts[i-1], b = p.pts[i];
    p.cum.push(p.cum[i-1] + Math.hypot(b[0]-a[0], b[1]-a[1]));
  }
  p.len = p.cum[p.cum.length - 1];
  p.offset = 0;
  p.dots = [];
});
function pointAt(p, d){
  d = ((d % p.len) + p.len) % p.len;
  for (let i = 1; i < p.cum.length; i++){
    if (p.cum[i] >= d){
      const a = p.pts[i-1], b = p.pts[i], seg = p.cum[i] - p.cum[i-1];
      const s = seg === 0 ? 0 : (d - p.cum[i-1]) / seg;
      return [a[0] + (b[0]-a[0])*s, a[1] + (b[1]-a[1])*s];
    }
  }
  return p.pts[p.pts.length - 1];
}
const dotsLayer = () => $('#dots');
const SVGNS = 'http://www.w3.org/2000/svg';
let lastT = 0;
function tick(t){
  requestAnimationFrame(tick);
  if (!S){ lastT = t; return; }
  const dt = Math.min(0.05, lastT ? (t - lastT) / 1000 : 0);
  lastT = t;
  for (const p of FLOW){
    const cur = p.cur();
    const active = cur > 5e-5;
    const speed = clamp(cur * 26000, 0, 240);
    p.offset = (p.offset + speed * dt) % p.len;
    const want = active ? Math.max(1, Math.floor(p.len / 72)) : 0;
    while (p.dots.length < want){
      const c = document.createElementNS(SVGNS, 'circle');
      c.setAttribute('r', '3.2');
      dotsLayer().appendChild(c);
      p.dots.push(c);
    }
    while (p.dots.length > want) dotsLayer().removeChild(p.dots.pop());
    const spacing = p.len / Math.max(1, want);
    for (let i = 0; i < p.dots.length; i++){
      const [x, y] = pointAt(p, p.offset + i * spacing);
      p.dots[i].setAttribute('cx', x.toFixed(1));
      p.dots[i].setAttribute('cy', y.toFixed(1));
    }
  }
}

