  $('#v_R1').textContent  = fmtR(VALUES.R1);
  $('#v_R2').textContent  = fmtR(VALUES.R2);
  $('#c1Val').textContent = (VALUES.C1 * 1e6).toFixed(0) + ' µF';

  // LED appearance
  const b = S.brightness;
  $('#d1glow').setAttribute('opacity', (b * 0.85).toFixed(3));
  $('#d1rays').setAttribute('opacity', b.toFixed(3));
  const tri = $('#d1tri');
  tri.setAttribute('fill', b > 0.004 ? 'rgba(255,210,63,' + (0.25 + 0.75*b).toFixed(3) + ')' : '#072F47');
  $('#d1burnt').setAttribute('display', S.burnt ? 'inline' : 'none');
