  }
  if (selectedNet){
    $('#netReadout').innerHTML = 'Net <b>' + selectedNet + '</b> — ' + fmtV(S.nodes[selectedNet]) + ' to gnd';
  }
}

function selectNet(net){
  selectedNet = (selectedNet === net) ? null : net;
  $$('.wire').forEach(w => w.classList.toggle('sel', w.dataset.net === selectedNet));
  $$('.junc').forEach(j => j.classList.toggle('sel', j.dataset.net === selectedNet));
  $$('.netrow').forEach(r => r.classList.toggle('sel', r.dataset.net === selectedNet));
  $('#netReadout').innerHTML = selectedNet
    ? 'Net <b>' + selectedNet + '</b> — ' + (S ? fmtV(S.nodes[selectedNet]) : '—') + ' to gnd'
    : 'No net selected. Click any wire to pin its voltage here.';
}

function renderMistakes(){
  const list = DATA.mistakes || [];
  $('#mistakeCount').textContent = String(list.length);
  $('#mistakeCap').textContent = mode === 'fixed'
    ? 'Showing the corrected circuit. These are the errors that were fixed.'
    : 'Showing the sketch exactly as drawn, checked against the intended design.';
  const ul = $('#mistakeList');
  ul.innerHTML = '';
  if (!list.length){
    const li = document.createElement('li');
    li.className = 'none';
    li.textContent = mode === 'fixed'
      ? 'None remaining. LED current is about 2 mA, well under its 20 mA rating.'
      : 'No mistakes found. The as-drawn sketch is wired correctly, with no shorts or reversed parts.';
    ul.appendChild(li);
  } else {
    list.forEach(m => {
      const li = document.createElement('li');
      li.textContent = m.text || String(m);
      ul.appendChild(li);
    });
  }
  // Red markers on the schematic for any mistakes that carry positions
  const g = $('#mistakeMarks');
  g.innerHTML = '';
  list.forEach((m, i) => {
    if (typeof m.x === 'number' && typeof m.y === 'number'){
      const cx = m.x * 720, cy = m.y * 340;
      const c = document.createElementNS(SVGNS, 'circle');
      c.setAttribute('cx', cx); c.setAttribute('cy', cy); c.setAttribute('r', 17);
      c.setAttribute('fill', 'none'); c.setAttribute('stroke', '#FF5A5A');
      c.setAttribute('stroke-width', '2.5'); c.setAttribute('stroke-dasharray', '5 4');
      g.appendChild(c);
      const t = document.createElementNS(SVGNS, 'text');
      t.setAttribute('x', cx); t.setAttribute('y', cy + 4); t.setAttribute('text-anchor', 'middle');
      t.setAttribute('font-size', '12'); t.setAttribute('font-weight', '700'); t.setAttribute('fill', '#FF5A5A');
      t.textContent = String(i + 1);
      g.appendChild(t);
    }
  });
}

function applyModeUI(){
  $('#modeFixed').classList.toggle('active', mode === 'fixed');
  $('#modeDrawn').classList.toggle('active', mode === 'drawn');
  $('#modeFixed').setAttribute('aria-pressed', String(mode === 'fixed'));
  $('#modeDrawn').setAttribute('aria-pressed', String(mode === 'drawn'));
  const chip = $('#modeChip');
  chip.textContent = mode === 'fixed' ? 'Fixed circuit' : 'As drawn';
  chip.className = 'chip ' + (mode === 'fixed' ? 'fixed' : 'drawn');
}

function solveAndRender(){
  solve();
  render();
}

/* ------------------------------------------------------------------ */
/* Interaction                                                          */
/* ------------------------------------------------------------------ */
const ohmsToPos = v => clamp((Math.log10(v) - 1) / 3, 0, 1) * 1000;
const posToOhms = p => Math.pow(10, 1 + 3 * (p / 1000));

function bindControls(){
  const sB1 = $('#s_B1'), sR1 = $('#s_R1'), sR2 = $('#s_R2');
  sB1.addEventListener('input', () => { VALUES.B1 = +sB1.value; solveAndRender(); });
  sR1.addEventListener('input', () => { VALUES.R1 = posToOhms(+sR1.value); solveAndRender(); });
  sR2.addEventListener('input', () => { VALUES.R2 = posToOhms(+sR2.value); solveAndRender(); });
  sR1.value = String(Math.round(ohmsToPos(VALUES.R1)));
  sR2.value = String(Math.round(ohmsToPos(VALUES.R2)));

  $('#resetBtn').addEventListener('click', () => {
    Object.assign(VALUES, DEFAULTS);
    sB1.value = String(VALUES.B1);
    sR1.value = String(Math.round(ohmsToPos(VALUES.R1)));
    sR2.value = String(Math.round(ohmsToPos(VALUES.R2)));
    solveAndRender();
  });

  $('#modeFixed').addEventListener('click', () => window.__sim.setMode('fixed'));
  $('#modeDrawn').addEventListener('click', () => window.__sim.setMode('drawn'));

  // Nets list
  const netList = $('#netList');
  for (const n of NET_INFO){
    const row = document.createElement('div');
    row.className = 'netrow';
    row.dataset.net = n.id;
    row.setAttribute('role', 'button');
    row.innerHTML = '<span><b>' + n.id + '</b><small>' + n.desc + '</small></span>' +
                    '<span class="netv" id="net_v_' + n.id + '">0.00 V</span>';
    row.addEventListener('click', () => selectNet(n.id));
    netList.appendChild(row);
  }

  // Click wires / background on the schematic
  const svg = $('#schematic');
  svg.addEventListener('click', e => {
    const netEl = e.target.closest && e.target.closest('[data-net]');
    if (netEl && netEl.dataset.net){ selectNet(netEl.dataset.net); return; }
    if (e.target.closest && e.target.closest('.part')) return;
    selectNet(selectedNet); // toggle off
    selectedNet = null;
    $$('.wire').forEach(w => w.classList.remove('sel'));
    $$('.junc').forEach(j => j.classList.remove('sel'));
    $$('.netrow').forEach(r => r.classList.remove('sel'));
    $('#netReadout').textContent = 'No net selected. Click any wire to pin its voltage here.';
  });

  // Hover tooltips on parts
  const tip = $('#tip');
  const panel = $('#schemPanel');
  const tipFor = id => {
    if (!S) return '';
    const n = S.nodes;
    switch (id){
      case 'B1': return '<b>B1</b> · ' + VALUES.B1.toFixed(1) + ' V battery<br>Delivers: ' + fmtI(S.iBatt) +
        '<br>Terminal voltage: ' + fmtV(n.vcc) + '<br>Internal resistance: 0.2 Ω';
      case 'R1': return '<b>R1</b> · ' + fmtR(VALUES.R1) + '<br>Current (vcc to n1): ' + fmtI(S.iR1) +
        '<br>Voltage: ' + fmtV(S.vR1);
      case 'C1': return '<b>C1</b> · ' + (VALUES.C1*1e6).toFixed(0) + ' µF, straight plate to n1<br>Current: 0.0 mA — open at DC' +
        '<br>Voltage: ' + fmtV(S.vC);
      case 'R2': return '<b>R2</b> · ' + fmtR(VALUES.R2) + '<br>Current (n1 to n2): ' + fmtI(S.iR2) +
        '<br>Voltage: ' + fmtV(S.vR2);
      case 'D1': return '<b>D1</b> · LED, Vf ' + LED_VF.toFixed(1) + ' V<br>Current (n2 to gnd): ' + fmtI(S.iLed) +
        '<br>Forward voltage: ' + fmtV(S.vLed) + '<br>Brightness: ' + Math.round(S.brightness * 100) + '% of 20 mA' +
        (S.burnt ? '<br><span class="warn">Burnt out — current exceeded 30 mA</span>' : '');
      default: return id;
    }
  };
  $$('.part').forEach(part => {
    const id = part.dataset.id;
    part.addEventListener('mouseenter', () => { tip.innerHTML = tipFor(id); tip.style.display = 'block'; });
    part.addEventListener('mousemove', e => {
      const rect = panel.getBoundingClientRect();
      let x = e.clientX - rect.left + 14, y = e.clientY - rect.top + 14;
      if (x + 250 > rect.width) x = e.clientX - rect.left - 244;
      if (y + 120 > rect.height) y = e.clientY - rect.top - 110;
      tip.style.left = x + 'px';
      tip.style.top  = y + 'px';
      tip.innerHTML = tipFor(id);
    });
    part.addEventListener('mouseleave', () => { tip.style.display = 'none'; });
  });
}

