window.__sim = {
  setMode(m){
    if (m !== 'fixed' && m !== 'drawn') return;
    mode = m;
    applyModeUI();
    renderMistakes();
    solveAndRender();
  },
  setSwitch(id, closed){
    SWITCHES[id] = !!closed;
    solveAndRender();
  },
  setValue(id, value){
    const v = +value;
    if (!isFinite(v) || !(id in VALUES)) return;
    VALUES[id] = v;
    // Keep the visible controls in sync
    if (id === 'B1') $('#s_B1').value = String(clamp(v, 0, 12));
    if (id === 'R1') $('#s_R1').value = String(Math.round(ohmsToPos(clamp(v, 10, 10000))));
    if (id === 'R2') $('#s_R2').value = String(Math.round(ohmsToPos(clamp(v, 10, 10000))));
    solveAndRender();
  },
  setPosition(id, p){
    POSITIONS[id] = clamp(+p || 0, 0, 1);
    solveAndRender();
  },
  state(){
    const nodes = { vcc: S.nodes.vcc, n1: S.nodes.n1, n2: S.nodes.n2, gnd: 0 };
    return {
      mode,
      nodes,
      parts: {
        B1: { current: S.iBatt, voltage: S.nodes.vcc - 0 },
        R1: { current: S.iR1,   voltage: S.vR1 },
        C1: { current: 0,       voltage: S.vC },
        R2: { current: S.iR2,   voltage: S.vR2 },
        D1: { current: S.iLed,  voltage: S.vLed, on: S.ledOn, brightness: S.brightness, burnt: S.burnt }
      }
    };
  }
};

